let log = find_block({ names: ["oak_log", "spruce_log", "birch_log", "cherry_log", "dark_oak_log", "pale_oak_log", "mangrove_log", "acacia_log", "jungle_log"], max_distance: 64 });
let walked = 0;
while (!log && walked < 4) {
  const here = position();
  await move_to(here.x + 36, here.y, here.z + 36);
  walked += 1;
  log = find_block({ names: ["oak_log", "spruce_log", "birch_log", "cherry_log", "dark_oak_log", "pale_oak_log", "mangrove_log", "acacia_log", "jungle_log"], max_distance: 64 });
}
if (!log) {
  const home = depot();
  await move_to(home.x + 4, home.y, home.z + 4);
  return { done: false, detail: 'no tree in four walks; going home' };
}
const chopped = await dig(log.x, log.y, log.z);
if (!chopped.ok) {
  return { done: false, detail: chopped.detail };
}
await leave_at_depot();
return { done: true, detail: 'walked to a tree, mined a log, left the bag at the depot' };
